from pathlib import Path

css = Path('app/site.css')
s = css.read_text()
marker = '/* Audio Player final screenshot polish */'
if marker not in s:
    s += '''\n\n@layer site-features {\n  /* Audio Player final screenshot polish */\n  .audio-player-volume {\n    background: transparent;\n    border: 0;\n    border-radius: 0;\n    box-shadow: none;\n    min-height: 0;\n    outline: 0;\n    padding: 0;\n  }\n  .audio-player-volume:focus-within {\n    background: transparent;\n    border: 0;\n    box-shadow: none;\n    outline: 0;\n  }\n\n  @media (min-width: 701px) {\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) { min-height: 334px; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-details { min-height: 276px; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-section-panel { max-height: 274px; }\n  }\n\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-mini {\n    align-items: center;\n    background: var(--site-paper);\n    display: grid;\n    gap: 1px 9px;\n    grid-template-columns: 38px minmax(0, 1fr) 30px;\n    grid-template-rows: 28px 14px;\n    min-height: 64px;\n    padding: 7px 10px 8px;\n    position: relative;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-mini-toggle {\n    grid-column: 1;\n    grid-row: 1 / 3;\n    height: 38px;\n    width: 38px;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-title {\n    display: block;\n    grid-column: 2;\n    grid-row: 1;\n    max-width: none;\n    min-width: 0;\n    padding: 0;\n    width: 100%;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-title strong {\n    display: block;\n    font-size: 10px;\n    line-height: 1.25;\n    max-width: none;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    width: 100%;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-title span { display: none; }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-mini-time {\n    align-items: end;\n    color: var(--site-muted);\n    display: flex;\n    font-family: var(--site-mono);\n    font-size: 8px;\n    grid-column: 2;\n    grid-row: 2;\n    justify-content: space-between;\n    line-height: 1;\n    width: 100%;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-mini-time > span:nth-child(2) { display: none; }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-expand {\n    grid-column: 3;\n    grid-row: 1 / 3;\n    height: 30px;\n    min-height: 30px;\n    min-width: 30px;\n    padding: 0;\n    width: 30px;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-edge-progress {\n    background: color-mix(in srgb, var(--site-line-strong) 50%, var(--site-paper));\n    border-radius: 1px;\n    bottom: 20px;\n    display: block;\n    height: 1px;\n    left: 57px;\n    overflow: visible;\n    position: absolute;\n    right: 39px;\n    top: auto;\n    z-index: 2;\n  }\n  .audio-player-dock.is-collapsed:not(.is-stowed) .audio-player-edge-progress > span {\n    background: var(--site-primary);\n    border-radius: 1px;\n    display: block;\n    height: 2px;\n    transform: translateY(-.5px);\n  }\n\n  @media (max-width: 700px) {\n    .audio-player-volume { min-width: 0; }\n    .audio-player-volume input[type="range"] { height: 14px; }\n  }\n}\n'''
css.write_text(s)
